trial.program_source:
def transform(grid):
    h,w=len(grid),len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0:
                color=grid[r][c]
                seen={(r,c)}; stack=[(r,c)]
                while stack:
                    y,x=stack.pop()
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                            seen.add((yy,xx)); stack.append((yy,xx))
                y0=min(y for y,x in seen); y1=max(y for y,x in seen)
                x0=min(x for y,x in seen); x1=max(x for y,x in seen)
                return [row[x0:x1+1] for row in grid[y0:y1+1]]
    return [row[:] for row in grid]

